reference_solution:
import sys
data = sys.stdin.read().split()
if data:
    n, target = int(data[0]), int(data[1])
    nums = [int(x) for x in data[2:2+n]]
    import bisect
    l = bisect.bisect_left(nums, target)
    r = bisect.bisect_right(nums, target) - 1
    if l <= r and l < n and nums[l] == target: print(f'{l} {r}')
    else: print('-1 -1')
else:
    print('-1 -1')
